@section('script')
<script>
document.addEventListener('DOMContentLoaded', function () {
    const requestSelect = document.getElementById('subscription-request');
    const subscriptionForm = document.getElementById('subscription-form');
    function prefillRequest() {
        if (!requestSelect || !subscriptionForm) return;
        const option = requestSelect.selectedOptions[0];
        ['vendor','product','plan','category'].forEach(name => { if (option.dataset[name]) subscriptionForm.elements[name].value = option.dataset[name]; });
        if (option.dataset.seats) subscriptionForm.elements.quantity.value = option.dataset.seats;
        if (option.dataset.cycle) subscriptionForm.elements.billing_cycle.value = option.dataset.cycle === 'yearly' ? 'annual' : option.dataset.cycle;
        if (option.dataset.currency) subscriptionForm.elements.currency.value = option.dataset.currency;
        if (option.dataset.budget) subscriptionForm.elements.unit_price.value = (Number(option.dataset.budget) / Math.max(1, Number(option.dataset.seats || 1))).toFixed(4);
        if (option.dataset.purpose) subscriptionForm.elements.business_purpose.value = option.dataset.purpose;
    }
    requestSelect?.addEventListener('change', prefillRequest); prefillRequest();
    if ({{ $prefillRequest ? 'true':'false' }}) bootstrap.Modal.getOrCreateInstance(document.getElementById('subscription-modal')).show();

    document.querySelectorAll('[data-lifecycle]').forEach(button => button.addEventListener('click', function () {
        document.getElementById('lifecycle-form').action = '{{ url('/admin/subscriptions') }}/' + this.dataset.id + '/transition';
        document.getElementById('lifecycle-label').textContent = this.dataset.label;
        bootstrap.Modal.getOrCreateInstance(document.getElementById('lifecycle-modal')).show();
    }));
    document.querySelectorAll('[data-evidence]').forEach(button => button.addEventListener('click', function () {
        document.getElementById('evidence-form').action = '{{ url('/admin/subscriptions') }}/' + this.dataset.id + '/evidence';
        document.getElementById('evidence-label').textContent = this.dataset.label;
        bootstrap.Modal.getOrCreateInstance(document.getElementById('evidence-modal')).show();
    }));
    document.querySelectorAll('[data-renewal]').forEach(button => button.addEventListener('click', function () {
        document.getElementById('renewal-form').action = '{{ url('/admin/subscriptions') }}/' + this.dataset.id + '/renewals';
        document.getElementById('renewal-label').textContent = this.dataset.label;
        bootstrap.Modal.getOrCreateInstance(document.getElementById('renewal-modal')).show();
    }));
    const decision = document.getElementById('renewal-decision');
    decision?.addEventListener('change', () => document.getElementById('changed-terms').classList.toggle('d-none', decision.value !== 'renew_changed'));
    document.querySelectorAll('[data-renewal-reject]').forEach(button => button.addEventListener('click', function () {
        document.getElementById('renewal-reject-form').action = this.dataset.action;
        bootstrap.Modal.getOrCreateInstance(document.getElementById('renewal-reject-modal')).show();
    }));
});
</script>
@endsection
